fn read_setting(key: Str) -> Result[Int, Str] {
  if key == "port" { return Ok(3000); }
  return Err("Not found");
}

fn get_port() -> Int {
  return read_setting("port").unwrap_or(8080);
}

fn get_host() -> Str {
  return "localhost";
}

fn main() -> Int {
  return get_port();
}
